mapper.select:
select odpr.order_record_id as billDetailId, date_format(br.crt_time, '%Y-%m-%d') as billDate, br.bill_number as billNum, odpr.patient_id as patientId, od.type as itemType, btd.itemCategoryId, btd.itemCategoryName, od.billing_item_id as itemId, btd.itemName, od.quantity as quantity, odpr.actual_receivable as itemActualAmount, br.actual_receivable_amount as billActualAmount, odpr.coupon_workload as itemSupplyWorkloadAmount from order_detail_pay_record odpr inner join order_detail od on odpr.order_detail_id = od.id left join ( select bt.id as itemId, bt.name as itemName, 0 as itemType, btc.id as itemCategoryId, btc.name as itemCategoryName from base_tariff bt left join base_tariff_category btc on bt.tariff_category_id = btc.id union all select bot.id as itemId, bot.name as itemName, 1 as itemType, botc.id as itemCategoryId, botc.name as itemCategoryName from base_oral_tariff bot left join base_oral_tariff_category botc on bot.oral_tariff_category_id = botc.id ) btd on od.type = btd.itemType and od.billing_item_id = btd.itemId inner join bill_record br on odpr.bill_record_id = br.id
date_format(odpr.crt_time, '%Y-%m') = #{query.currentMonth}
and odpr.org_id = #{query.orgId} and br.org_id = #{query.orgId} and od.org_id = #{query.orgId}
order by br.crt_time desc

SELECT od.order_record_id AS orderRecordId, ${billPayId} AS billPayId, od.id AS orderDetailId, od.type AS itemType, od.billing_item_id AS itemId, od.executor_id AS executorId, od.consulter_id AS consulterId, odpr.actual_receivable AS actualReceivable, IFNULL(bd.tariffActualAmount, 0) AS tariffActualAmount, IFNULL(bd.oralActualAmount, 0) AS oralActualAmount, IFNULL(bdp.free_amount, 0) AS itemFreeAmount, IFNULL(bdp.received_amount, 0) AS itemRecAmount FROM order_detail od LEFT JOIN order_detail_pay_record odpr ON odpr.order_detail_id = od.id LEFT JOIN ( SELECT od.order_record_id, SUM(IF(od.type=0, odpr.actual_receivable, 0)) AS tariffActualAmount, SUM(IF(od.type=1, odpr.actual_receivable, 0)) AS oralActualAmount FROM order_detail od LEFT JOIN order_detail_pay_record odpr ON odpr.order_detail_id = od.id
od.inservice = true AND odpr.inservice = true AND odpr.order_record_id = #{orderRecordId}
GROUP BY od.order_record_id ) bd ON bd.order_record_id=od.order_record_id LEFT JOIN ( SELECT order_record_id, item_type, item_id, sum(free_amount) AS free_amount, sum(received_amount) AS received_amount FROM bill_pay_share_detail
order_record_id = #{orderRecordId} AND bill_pay_id < #{billPayId}
group by order_record_id, item_type, item_id ) bdp ON bdp.order_record_id=od.order_record_id and od.type=bdp.item_type and od.billing_item_id=bdp.item_id
od.inservice = true AND od.receivable_amount > 0 AND odpr.inservice = true AND odpr.order_record_id = #{orderRecordId}
ORDER BY od.type, od.billing_item_id
